import { useCallback, useState } from 'react';
// prettier-ignore
export const useFocusable = ({
  nodes,
  type,
  defaultSelected
}) => {
  /*
   * We purposefully want to focus on the first node if defaultSelected is empty,
   * with the assumption that the tree is fully collapsed.
   */
  const [focusedNode, setFocusedNode] = useState(type && defaultSelected?.length ? defaultSelected[0] : nodes[0].id);
  const onFocus = useCallback(nodeId => {
    setFocusedNode(nodeId);
  }, []);
  return {
    focusedNode,
    onFocus
  };
};